605	func TestSelectAddressReplacementKeepsRotation(t *testing.T) {
606		// One instance keeps its id but gets a new address: the registration bumps
607		// once, that instance resets to unknown/0 while untouched instances keep
608		// their observations, and the rotation continues after the last chosen id
609		// instead of restarting at the smallest id.
610		input := `{"requests":[
611			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"},{"id":"d","address":"h4:4"}]},
612			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":11,"healthy":true},
613			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":12,"healthy":true},
614			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":13,"healthy":true},
615			{"type":"health","service":"svc","instanceId":"d","expectedRevision":1,"sequence":14,"healthy":false,"reason":"connection refused"},
616			{"type":"select","service":"svc","expectedRevision":1},
617			{"type":"select","service":"svc","expectedRevision":1},
618			{"type":"register","service":"svc","expectedRevision":1,"instances":[{"id":"a","address":"h9:9"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"},{"id":"d","address":"h4:4"}]},
619			{"type":"select","service":"svc","expectedRevision":2},
620			{"type":"select","service":"svc","expectedRevision":2}
621		]}`
622		out, code := runRegisterWith(t, input)
623		if code != 0 {
624			t.Fatalf("exit code: %d, output: %s", code, out)
625		}
626		var got registerOutput
627		if err := json.Unmarshal([]byte(out), &got); err != nil {
628			t.Fatalf("output is not JSON: %v\n%s", err, out)
629		}
630		if len(got.Results) != 10 {
631			t.Fatalf("results: %+v", got.Results)
632		}
633		// Rotation before the replacement: a then b, cursor rests on b.
634		if r := got.Results[5]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 11 {
635			t.Fatalf("first select: %+v", r)
636		}
637		if r := got.Results[6]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 {
638			t.Fatalf("second select: %+v", r)
639		}
640		// The address-only replacement succeeds and bumps the revision exactly once.
641		if r := got.Results[7]; !r.OK || !r.Changed || r.Revision != 2 {
642			t.Fatalf("address replacement: %+v", r)
643		}
644		// The new address of a has no observation yet, so it is skipped; the
645		// rotation continues just after b and lands on c, never on a's old address.
646		if r := got.Results[8]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 13 || r.Revision != 2 {
647			t.Fatalf("select after replacement should continue after b at c: %+v", r)
648		}
649		// Past the end the rotation wraps to the smallest eligible id (b), proving
650		// it did not restart from the smallest id because of the replacement.
651		if r := got.Results[9]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 || r.Revision != 2 {
652			t.Fatalf("select should wrap to smallest eligible id: %+v", r)
653		}
654		// Final state: a is unknown at sequence 0 with no leftover reason; the
655		// untouched instances keep their health, sequence and reason.
656		if len(got.Services) != 1 || got.Services[0].Revision != 2 {
657			t.Fatalf("services: %+v", got.Services)
658		}
659		insts := got.Services[0].Instances
660		if len(insts) != 4 {
661			t.Fatalf("instances: %+v", insts)
662		}
663		if insts[0].ID != "a" || insts[0].Address != "h9:9" || insts[0].Health != "unknown" || insts[0].Sequence != 0 || insts[0].Reason != "" {
664			t.Fatalf("replaced instance should reset to unknown/0: %+v", insts[0])
665		}
666		if insts[1].ID != "b" || insts[1].Health != "healthy" || insts[1].Sequence != 12 {
667			t.Fatalf("b should keep its observation: %+v", insts[1])
668		}
669		if insts[2].ID != "c" || insts[2].Health != "healthy" || insts[2].Sequence != 13 {
670			t.Fatalf("c should keep its observation: %+v", insts[2])
671		}
672		if insts[3].ID != "d" || insts[3].Health != "unhealthy" || insts[3].Sequence != 14 || insts[3].Reason != "connection refused" {
673			t.Fatalf("d should keep its observation and reason: %+v", insts[3])
674		}
675	}
