677	func TestSelectAddressReplacementNoHealthyThenRecovery(t *testing.T) {
678		// Replacing the only healthy instance's address leaves no healthy target:
679		// select reports no_healthy without moving the cursor, a health report
680		// against the old revision conflicts without healing the new address, and
681		// a fresh observation at the current revision (sequence only above the
682		// reset 0, not above the old accepted one) makes the new address eligible
683		// again.
684		input := `{"requests":[
685			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"}]},
686			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":20,"healthy":true},
687			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":21,"healthy":false,"reason":"down"},
688			{"type":"select","service":"svc","expectedRevision":1},
689			{"type":"register","service":"svc","expectedRevision":1,"instances":[{"id":"a","address":"h9:9"},{"id":"b","address":"h2:2"}]},
690			{"type":"select","service":"svc","expectedRevision":2},
691			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":99,"healthy":true},
692			{"type":"select","service":"svc","expectedRevision":2},
693			{"type":"health","service":"svc","instanceId":"a","expectedRevision":2,"sequence":1,"healthy":true},
694			{"type":"health","service":"svc","instanceId":"b","expectedRevision":2,"sequence":22,"healthy":true},
695			{"type":"select","service":"svc","expectedRevision":2},
696			{"type":"select","service":"svc","expectedRevision":2}
697		]}`
698		out, code := runRegisterWith(t, input)
699		if code != 1 {
700			t.Fatalf("exit code: %d, output: %s", code, out)
701		}
702		var got registerOutput
703		if err := json.Unmarshal([]byte(out), &got); err != nil {
704			t.Fatalf("output is not JSON: %v\n%s", err, out)
705		}
706		if len(got.Results) != 12 {
707			t.Fatalf("results: %+v", got.Results)
708		}
709		// Cursor rests on a before the replacement.
710		if r := got.Results[3]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 20 {
711			t.Fatalf("select before replacement: %+v", r)
712		}
713		if r := got.Results[4]; !r.OK || !r.Changed || r.Revision != 2 {
714			t.Fatalf("address replacement: %+v", r)
715		}
716		// No healthy instance remains: no_healthy states the reason and the current
717		// revision and fabricates neither an instance id nor an address.
718		if r := got.Results[5]; r.OK || r.Error != "no_healthy" || r.Reason == "" || r.Revision != 2 || r.InstanceID != "" || r.Address != "" {
719			t.Fatalf("no_healthy after replacement: %+v", r)
720		}
721		// A health report against the old revision conflicts even though its
722		// sequence (99) exceeds the old accepted one (20); it names both revisions.
723		if r := got.Results[6]; r.OK || r.Error != "conflict" || r.Reason == "" || r.ExpectedRevision != 1 || r.ActualRevision != 2 || r.Revision != 2 {
724			t.Fatalf("stale-revision health report: %+v", r)
725		}
726		// The conflicting report did not heal the new address: still no_healthy.
727		if r := got.Results[7]; r.OK || r.Error != "no_healthy" || r.Revision != 2 || r.InstanceID != "" || r.Address != "" {
728			t.Fatalf("new address must not regain eligibility from old revision: %+v", r)
729		}
730		// At the current revision a sequence just above the reset 0 suffices; it
731		// does not need to exceed the 20 accepted for the old address.
732		if r := got.Results[8]; !r.OK || !r.Changed || r.Revision != 2 || r.Sequence != 1 {
733			t.Fatalf("fresh observation at current revision: %+v", r)
734		}
735		if r := got.Results[9]; !r.OK || !r.Changed || r.Revision != 2 || r.Sequence != 22 {
736			t.Fatalf("b recovery: %+v", r)
737		}
738		// The failed selects and health report never moved the cursor off a, so
739		// the rotation continues at b rather than restarting at the smallest id.
740		if r := got.Results[10]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 22 || r.Revision != 2 {
741			t.Fatalf("rotation should resume after a at b: %+v", r)
742		}
743		// The new address rejoins selection carrying its new address and the new
744		// observation's sequence.
745		if r := got.Results[11]; !r.OK || r.InstanceID != "a" || r.Address != "h9:9" || r.Sequence != 1 || r.Revision != 2 {
746			t.Fatalf("new address should be selected with its new observation: %+v", r)
747		}
748		// The final list reflects only the committed changes.
749		if len(got.Services) != 1 || got.Services[0].Revision != 2 {
750			t.Fatalf("services: %+v", got.Services)
751		}
752		insts := got.Services[0].Instances
753		if len(insts) != 2 {
754			t.Fatalf("instances: %+v", insts)
755		}
756		if insts[0].ID != "a" || insts[0].Address != "h9:9" || insts[0].Health != "healthy" || insts[0].Sequence != 1 || insts[0].Reason != "" {
