cd /tmp/idxcases
python3 - <<'EOF'
import json, random, subprocess, sys

random.seed(20261003)
types = ["register", "health", "select", "", "probe", None]

def rand_inst():
    ids = ["a", "b", "c", "i1", "i2", "x", ""]
    addrs = ["h1:1", "h2:8080", "10.0.0.1:443", "[::1]:80", "nope", "", "host:notaport", "example.com:65535"]
    return {"id": random.choice(ids), "address": random.choice(addrs)}

def rand_req():
    t = random.choice(types)
    base = {}
    if t is not None:
        base["type"] = t
    if random.random() < 0.85: base["service"] = random.choice(["svc", "s2", " ", "ghost", "svc"])
    if random.random() < 0.9: base["expectedRevision"] = random.choice([0, 1, 2, 3, 9, -1, "1", 1.5])
    if t in ("register", ""):
        if random.random() < 0.9:
            base["instances"] = [rand_inst() for _ in range(random.randrange(4))]
        elif random.random() < 0.5:
            base["instances"] = {}
    elif t == "health":
        base["instanceId"] = random.choice(["a", "b", "ghost", " "])
        base["sequence"] = random.choice([0, 1, 2, 5, 6, -2, "1", 1.5])
        h = random.choice([True, False, "yes", 1, None])
        if h is not None: base["healthy"] = h
        if h is False or (random.random() < 0.5): base["reason"] = random.choice(["down", "  ", "", 5])
    return base

bad_shapes = [5, "x", [], [1], {"nested": True}, None]

mismatch = 0
for i in range(400):
    n = random.randrange(9)
    reqs = []
    for _ in range(n):
        reqs.append(random.choice(bad_shapes) if random.random() < 0.1 else rand_req())
    payload = json.dumps({"requests": reqs})
    old = subprocess.run(["/tmp/indexroom-old", "register"], input=payload, capture_output=True, text=True)
    new = subprocess.run(["/tmp/indexroom-new", "register"], input=payload, capture_output=True, text=True)
    if old.stdout != new.stdout or old.returncode != new.returncode or old.stderr != new.stderr:
        mismatch += 1
        print("MISMATCH on:", payload)
        print("old:", old.returncode, old.stdout[:300])
        print("new:", new.returncode, new.stdout[:300])
        if mismatch >= 3: sys.exit(1)
print("fuzz done, mismatches:", mismatch)
EOF
